 36	pub struct Policy<'a> {
 37	    insured: &'a [Item],
 38	}
 39	
 40	impl<'a> Policy<'a> {
 41	    pub fn insuring(items: &'a [Item]) -> Self {
 42	        Policy { insured: items }
 43	    }
 44	
 45	    /// The insured item a reported damage refers to.
 46	    fn damaged_item(&self, damage: &Damage) -> Option<&Item> {
 47	        self.insured
 48	            .iter()
 49	            .find(|item| item.item_type == damage.item_type)
 50	    }
 51	
 52	    /// A settlement totals what the office reimburses for each damage the
 53	    /// incident reported.
 54	    pub fn claim(&self, damages: &[Damage]) -> Settlement {
 55	        let reimbursed: f64 = damages
 56	            .iter()
 57	            .map(|damage| damage_reimbursement(damage, self.damaged_item(damage)))
 58	            .sum();
 59	        settle_within_cap(self.insured, round_payout_in_mhpco_favor(reimbursed))
 60	    }
 61	}
 62	
 63	/// A premium is rounded in the MHPCO's favor, which for money the customer
 64	/// owes the office means upwards.
 65	fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
 66	    premium.ceil() as i64
 67	}
 68	
 69	/// A payout is rounded in the MHPCO's favor, which for money the office owes
 70	/// the claimant means downwards. Only the settlement total is rounded; the
 71	/// reimbursements it sums are carried as fractions.
 72	fn round_payout_in_mhpco_favor(payout: f64) -> i64 {
 73	    payout.floor() as i64
 74	}
 75	
 76	/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
 77	/// modifiers scale the policy base premium, while item-specific modifiers are
 78	/// measured against their own item's base premium and are added alongside, so
 79	/// a curse never surcharges the rest of the policy.
 80	fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
 81	    let base = policy_base_premium(items);
 82	    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
 83	}
 84	
 85	pub fn quote(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
 86	    let premium = premium_before_fee(customer, items, previous_quotes);
 87	    round_premium_in_mhpco_favor(premium) + PROCESSING_FEE
 88	}
