     1	//! What the MHPCO reimburses for a single reported damage: the clauses the
     2	//! office applies to one damage amount before it reaches the settlement.
     3	//!
     4	//! This is the claim side's judgement of a single damage event. It changes
     5	//! when the office revises its clauses -- a steeper deductible, a new
     6	//! material that is fully covered, a different enchantment level -- quite
     7	//! independently of the policy-wide limits on what a settlement may total,
     8	//! and independently of how the premium side assessed the same item's risk.
     9	
    10	use crate::{Damage, Item};
    11	
    12	/// A deductible applies per damage event.
    13	const DEDUCTIBLE: f64 = 100.0;
    14	
    15	/// Damage to an item enchanted at this level or above is reimbursed at half.
    16	const HALF_REIMBURSEMENT_LEVEL: i64 = 8;
    17	
    18	/// The share of the damage that clause reimburses.
    19	const HALF_REIMBURSEMENT_SHARE: f64 = 0.5;
    20	
    21	/// With no clause cutting it down, the MHPCO reimburses a damage in full.
    22	const FULL_REIMBURSEMENT_SHARE: f64 = 1.0;
    23	
    24	/// Whether the half-reimbursement clause applies to an insured item. The claim
    25	/// side judges high enchantment by its own level, well above the one the
    26	/// premium side surcharges for.
    27	fn half_reimbursement_applies(item: &Item) -> bool {
    28	    item.enchantment >= HALF_REIMBURSEMENT_LEVEL
    29	}
    30	
    31	/// Which share of a reported damage the office's clauses cover. The MHPCO
    32	/// reimburses in full unless a clause of its own cuts the share down, and a
    33	/// damage to no recognised item meets no clause at all.
    34	fn reimbursement_share(damaged: Option<&Item>) -> f64 {
    35	    if damaged.is_some_and(half_reimbursement_applies) {
    36	        HALF_REIMBURSEMENT_SHARE
    37	    } else {
    38	        FULL_REIMBURSEMENT_SHARE
    39	    }
    40	}
    41	
    42	/// How much of a reported damage the office covers, before the deductible.
    43	fn covered_amount(damage: &Damage, damaged: Option<&Item>) -> f64 {
    44	    damage.amount as f64 * reimbursement_share(damaged)
    45	}
    46	
    47	/// What the MHPCO reimburses for one reported damage: the share of the
    48	/// damage the office covers, less the deductible the claimant bears
    49	/// themselves.
    50	///
    51	/// The amount is carried as a fraction: the MHPCO keeps intermediate amounts
    52	/// unrounded and rounds only the settlement the claimant is finally paid.
    53	pub(crate) fn damage_reimbursement(damage: &Damage, damaged: Option<&Item>) -> f64 {
    54	    covered_amount(damage, damaged) - DEDUCTIBLE
    55	}
